select pg_temp.check('review preserves original linked occurrence identity','LINKED_EVENT',(select occurrence_key=pg_temp.result('linked-key')->>'value' and event_context_stamp=boss_private.volunteer_event_stamp(event_id,occurrence_key) from public.volunteer_shifts where id=pg_temp.id('linked-shift')));
select pg_temp.check('reviewed Calendar-change notification ceases current visibility','LINKED_EVENT',not exists(select 1 from public.notification_events e where e.source_type='volunteer_event' and e.source_id=pg_temp.f('linked-event') and boss_private.notification_source_visible(e,pg_temp.f('parent'))));
select pg_temp.check('review emits one replacement reminder context while retaining history','LINKED_EVENT',(select count(*)=2 and count(*) filter(where boss_private.notification_source_visible(e,pg_temp.f('parent')))=1 from public.notification_events e where e.source_id=pg_temp.id('linked-signup') and e.event_type='volunteer.reminder'));
select pg_temp.check('replacement linked reminder remains future queued','LINKED_EVENT',(select count(*)=1 and bool_and(status='queued' and scheduled_at>now()) from public.notification_events e where e.source_id=pg_temp.id('linked-signup') and e.event_type='volunteer.reminder' and boss_private.notification_source_visible(e,pg_temp.f('parent'))));

-- A selected-volunteer announcement is a regular private Messaging thread.
