select pg_temp.save('announcement',public.boss_volunteers_mutate(pg_temp.f('announcement'),pg_temp.cmd('shift.announce',jsonb_build_object('shift_id',pg_temp.id('shift'),'title','Synthetic volunteer notice','body','Synthetic controlled integration content'))));
select pg_temp.check('coach generic Messaging read succeeds before policy change','ANNOUNCEMENT',jsonb_array_length(public.boss_communications_read(pg_temp.thread_query())->'detail'->'messages')=1);
