select pg_temp.save('attachment',public.boss_communications_mutate(pg_temp.f('attachment-intent'),pg_temp.cmd('attachment.intent',jsonb_build_object('thread_id',pg_temp.id('announcement'),'file_name','synthetic-empty.pdf','mime_type','application/pdf','size_bytes',100,'content_sha256',repeat('a',64)))));
reset role;
insert into storage.objects(bucket_id,name,metadata) values('boss-communication-attachments',pg_temp.result('attachment')->>'object_name','{"mimetype":"application/pdf","size":100}'::jsonb);
