select pg_temp.save('attachment-complete',public.boss_communications_mutate(pg_temp.f('attachment-complete'),pg_temp.cmd('attachment.complete',jsonb_build_object('attachment_id',pg_temp.id('attachment')))));
select pg_temp.save('coach-attachment-access',public.boss_communications_mutate(pg_temp.f('coach-attachment-access'),pg_temp.cmd('attachment.access',jsonb_build_object('attachment_id',pg_temp.id('attachment')))));
select set_config('storage.operation','object.get_authenticated',true);
select pg_temp.check('coach synthetic private object read allowed before change','ATTACHMENT',(select count(*)=1 from storage.objects where bucket_id='boss-communication-attachments' and name=pg_temp.result('attachment')->>'object_name'));
select pg_temp.actor('parent');
select pg_temp.check('selected guardian volunteer reads normal Messaging without legacy flags','ANNOUNCEMENT',jsonb_array_length(public.boss_communications_read(pg_temp.thread_query())->'detail'->'messages')=1);
select pg_temp.save('parent-thread-read',public.boss_communications_mutate(pg_temp.f('parent-thread-read'),pg_temp.cmd('read.thread',jsonb_build_object('thread_id',pg_temp.id('announcement'),'through_sequence',1))));
select pg_temp.save('parent-attachment-access',public.boss_communications_mutate(pg_temp.f('parent-attachment-access'),pg_temp.cmd('attachment.access',jsonb_build_object('attachment_id',pg_temp.id('attachment')))));
select pg_temp.check('selected volunteer reads synthetic attachment metadata only','ATTACHMENT',(select count(*)=1 from storage.objects where bucket_id='boss-communication-attachments' and name=pg_temp.result('attachment')->>'object_name'));
select pg_temp.check('selected announcement reaches generic notification inbox','ANNOUNCEMENT',(select count(*)=1 from jsonb_array_elements(pg_temp.notifications('communications')->'notifications')n where n->>'event_type'='communication.announcement'));
select pg_temp.actor('staff');
select pg_temp.denied('same team staff without active assignment cannot read selected thread',format('select public.boss_communications_read(%L)',pg_temp.thread_query()));
select pg_temp.denied('same team staff cannot forge selected attachment',format('select public.boss_communications_mutate(%L,%L)',pg_temp.f('staff-attachment'),pg_temp.cmd('attachment.access',jsonb_build_object('attachment_id',pg_temp.id('attachment')))));
