select pg_temp.denied('other tenant administrator cannot read selected thread',format('select public.boss_communications_read(%L)',pg_temp.thread_query()));
reset role;
select pg_temp.check('selected audience remains private exact shift only','ANNOUNCEMENT',(select t.kind='announcement' and t.visibility='private' and count(a.id)=1 and bool_and(a.volunteer_shift_id=pg_temp.id('shift') and a.scope_type='team' and a.scope_id=pg_temp.f('team')) from public.communication_threads t join public.communication_audiences a on a.thread_id=t.id where t.id=pg_temp.id('announcement') group by t.kind,t.visibility));
select pg_temp.check('selected announcement notification excludes unrelated team members','ANNOUNCEMENT',not exists(select 1 from public.notifications n join public.notification_events e on e.id=n.notification_event_id join public.communication_messages m on m.id=e.source_id where m.thread_id=pg_temp.id('announcement') and n.recipient_person_id in(pg_temp.f('staff'),pg_temp.f('parent2'),pg_temp.f('household-only'),pg_temp.f('other-admin'))));
-- now() is fixed in a rollback-only transaction. Give the later commitment a
-- synthetic one-microsecond ordering boundary to represent a subsequent signup
-- transaction without sleeping, committing fixtures or rewriting source rows.
set local role authenticated;select pg_temp.actor('parent2');
select pg_temp.save('post-announcement-signup',public.boss_volunteers_mutate(pg_temp.f('post-announcement-signup'),pg_temp.cmd('assignment.signup',jsonb_build_object('shift_id',pg_temp.id('shift')))));
reset role;
update public.volunteer_assignments set updated_at=now()+interval '1 microsecond' where id=pg_temp.id('post-announcement-signup');
select pg_temp.check('post-source assignment excluded from historical announcement visibility','SOURCE_DATED',not exists(select 1 from public.notification_events e join public.communication_messages m on m.id=e.source_id where m.thread_id=pg_temp.id('announcement') and boss_private.notification_source_visible(e,pg_temp.f('parent2'))));
select pg_temp.check('post-source assignment excluded from historical candidate seek','SOURCE_DATED',not exists(select 1 from public.notification_events e join public.communication_messages m on m.id=e.source_id cross join lateral boss_private.notification_candidates(e,null,100)c where m.thread_id=pg_temp.id('announcement') and c.person_id=pg_temp.f('parent2')));
select pg_temp.check('existing volunteer retains source-dated announcement visibility','SOURCE_DATED',exists(select 1 from public.notification_events e join public.communication_messages m on m.id=e.source_id where m.thread_id=pg_temp.id('announcement') and boss_private.notification_source_visible(e,pg_temp.f('parent'))));
select pg_temp.check('historical announcement creates no retroactive recipient row','SOURCE_DATED',not exists(select 1 from public.notifications n join public.notification_events e on e.id=n.notification_event_id join public.communication_messages m on m.id=e.source_id where m.thread_id=pg_temp.id('announcement') and n.recipient_person_id=pg_temp.f('parent2')));
set local role authenticated;select pg_temp.actor('parent2');
select pg_temp.check('current selected volunteer may read current thread after joining','SOURCE_DATED',jsonb_array_length(public.boss_communications_read(pg_temp.thread_query())->'detail'->'messages')=1);
